    wire w393 = w392 ^ r390_2 ^ r388_2;
    wire w394 = ( w392 & r390_2 ) | ( w392 & r388_2 ) | ( r390_2 & r388_2 );
    wire w395 = w386 ^ w393;
    wire w396 = w386 & w393;
    wire w397 = w394 ^ w396;
    wire w398 = w394 & w396;
    reg r263_3, r331_3, r365_3, r383_3, r391_3, r395_3, r397_3, r398_3;
    always @(posedge clk) begin
        r263_3 <= r263_2;
        r331_3 <= r331_2;
        r365_3 <= r365_2;
        r383_3 <= r383_2;
        r391_3 <= w391;
        r395_3 <= w395;
        r397_3 <= w397;
        r398_3 <= w398;
    end

    // ---- outputs ----
    assign hw[0] = r263_3;
    assign hw[1] = r331_3;
    assign hw[2] = r365_3;
    assign hw[3] = r383_3;
    assign hw[4] = r391_3;
    assign hw[5] = r395_3;
    assign hw[6] = r397_3;
    assign hw[7] = r398_3;

    // tag and valid ride alongside the operands
    reg [7:0] tagPipe [0:2];
    reg [2:0] validPipe;
    integer s;
    always @(posedge clk) begin
        tagPipe[0] <= tagIn;
        for (s = 1; s < 3; s = s + 1)
            tagPipe[s] <= tagPipe[s-1];
        validPipe <= {validPipe[1:0], validIn};
    end
    assign tagOut = tagPipe[2];
    assign validOut = validPipe[2];

    // distinguished point: HW(x) <= cutoff, one comparator
    assign dp = (hw <= cutoff);

endmodule
`default_nettype wire
